Lemma pd_L : forall (fx : FPState) regs (m : word -> option byte) (s pa parr i : Z),
  (4096 + 48 <= s <= 2 ^ 47)%Z ->
  (4096 <= pa)%Z ->
  (pa + 32 <= 2 ^ 47)%Z ->
  (0 <= parr)%Z ->
  (parr + 80 <= 2 ^ 47)%Z ->
  (0 <= i <= 9)%Z ->
  rdn SEGS m (Z_to_bv 64 (pa + 16)) 8 = Some (Z_to_le_bytes 8 parr) ->
  getr regs 2 = Z_to_bv 64 (s - 48) ->
  getr regs 8 = Z_to_bv 64 pa ->
  getr regs 18 = Z_to_bv 64 (8 * i) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 98680) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 103464) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 98692 /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 10 = Z_to_bv 64 (parr + 8 * i) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
