Lemma pd_B : forall (fx : FPState) regs (m : word -> option byte) (s pa parr : Z),
  (4096 + 48 <= s <= 2 ^ 47)%Z ->
  (4096 <= pa)%Z ->
  (pa + 32 <= 2 ^ 47)%Z ->
  (0 <= parr < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (pa + 16)) 8 = Some (Z_to_le_bytes 8 parr) ->
  getr regs 2 = Z_to_bv 64 (s - 48) ->
  getr regs 8 = Z_to_bv 64 pa ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 98708) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 194572) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 98716 /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 8 = Z_to_bv 64 pa /\ getr regs' 10 = Z_to_bv 64 parr /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
