Lemma pd_C : forall (fx : FPState) regs (m : word -> option byte) (s pa : Z),
  (4096 + 48 <= s <= 2 ^ 47)%Z ->
  (4096 <= pa)%Z ->
  (pa + 32 <= 2 ^ 47)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 48) ->
  getr regs 8 = Z_to_bv 64 pa ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 98716) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 101432) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 98724 /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 8 = Z_to_bv 64 pa /\ getr regs' 10 = Z_to_bv 64 (pa + 24) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
