Lemma bd_B : forall (fx : FPState) regs (m : word -> option byte) (s ba : Z),
  (4096 + 96 <= s <= 2 ^ 47)%Z ->
  (0 <= ba < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 96) ->
  getr regs 8 = Z_to_bv 64 ba ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 101760) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 194572) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 101768 /\ getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 10 = Z_to_bv 64 ba /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
